 				map->m_pblk = 0;
 				goto sync_out;
 			}
 			if (flag == F2FS_GET_BLOCK_PRECACHE)
 				goto sync_out;
 			if (flag == F2FS_GET_BLOCK_FIEMAP &&
 						blkaddr == NULL_ADDR) {
 				if (map->m_next_pgofs)
 					*map->m_next_pgofs = pgofs + 1;
 				goto sync_out;
 			}
 			if (flag != F2FS_GET_BLOCK_FIEMAP) {
 				/* for defragment case */
 				if (map->m_next_pgofs)
 					*map->m_next_pgofs = pgofs + 1;
 				goto sync_out;
 			}
 		}
 	}

